do $$ begin
 if exists(select 1 from public.catalogue_parallel_rules t join desired_catalogue_parallel_rules e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.parallel_group is distinct from e.parallel_group or t.applies_to is distinct from e.applies_to or t.parallel is distinct from e.parallel or t.serial_cap is distinct from e.serial_cap or t.serial_exact is distinct from e.serial_exact or t.exclusive_note is distinct from e.exclusive_note or t.numbering_note is distinct from e.numbering_note or t.verification_status is distinct from e.verification_status)
 then raise exception 'Conflicting catalogue_parallel_rules identity; refusing overwrite'; end if;
end $$;
insert into public.catalogue_parallel_rules(id,set_id,parallel_group,applies_to,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status) select id,set_id,parallel_group,applies_to,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status from desired_catalogue_parallel_rules on conflict do nothing;
create temporary table desired_catalogue_sources on commit drop as select * from jsonb_populate_recordset(null::public.catalogue_sources,'[{"id":"2025-topps-star-wars-smugglers-outpost-checklist","set_id":"2025-topps-star-wars-smugglers-outpost","source":"Topps","purpose":"Checklist","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/2025_Star_Wars_Smugglers_Outpost_Checklist.pdf?v=1787961928","notes":"29-page manufacturer PDF. Numbered sketch designs retained; artist roster does not create additional identities."},{"id":"2025-topps-star-wars-smugglers-outpost-odds","set_id":"2025-topps-star-wars-smugglers-outpost","source":"Topps","purpose":"Parallel applicability","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/2025_Star_Wars_Smugglers_Outpost_Odds.pdf?v=1787961928","notes":"7-page manufacturer odds. Subset rules only; no inferred serial caps or card-specific applicability."},{"id":"2025-topps-star-wars-smugglers-outpost-product","set_id":"2025-topps-star-wars-smugglers-outpost","source":"Topps","purpose":"Release and product scope","url":"https://www.topps.com/products/2025-topps-star-wars-smugglers-outpost-hobby-box","notes":"2025 title; manufacturer Available From March 18, 2026. Generic product-year metadata 2026; title year retained."}]'::jsonb);
